-- Generated by tools/build/to-sql.js. Do not edit by hand.
-- Idempotent: reloading content never touches attempts, serves, mocks or gaps.

-- Production schema for the tutor backend.
--
-- The governing rule: nothing is stored that can be derived. Every number the
-- student or parent sees is a query over `attempts`, joined to `topics` for
-- weights.
--
-- MIGRATING A DATABASE THAT ALREADY EXISTS. Every CREATE TABLE below is
-- IF NOT EXISTS, which is what makes reloading this file (and worker/seed.sql,
-- which embeds it verbatim) safe against real evidence — and it also means a
-- table that already exists does NOT gain a column that was added here later.
-- Each such column is listed below with the ALTER an existing database needs;
-- there is no `ADD COLUMN IF NOT EXISTS` in SQLite, so it cannot be expressed
-- as part of this file without breaking the reload guarantee.
--
--   ALTER TABLE attempts ADD COLUMN picked TEXT;   -- the option a graded mcq
--                                                  -- answer resolved to
--
-- db.js detects that column's absence and keeps recording answers without it
-- rather than failing every /log, so an unmigrated database degrades to "the
-- distractor was not recorded" instead of "the answer was not recorded".

CREATE TABLE IF NOT EXISTS items (
  id            TEXT PRIMARY KEY,
  subject       TEXT NOT NULL,
  topic         TEXT,
  unit          TEXT,
  practice      TEXT,
  kind          TEXT NOT NULL,          -- mcq | constructed | frq | constructed_model_graded
  stem          TEXT NOT NULL,
  options_json  TEXT,                   -- {"A":"..","B":".."} for mcq
  answer        TEXT,                   -- keyed letter, or canonical short answer
  answer_variants_json TEXT,            -- accepted alternate spellings/forms
  explanation   TEXT,
  rubric_json   TEXT,                   -- frq only
  difficulty    TEXT,
  calc_allowed  INTEGER
);
CREATE INDEX IF NOT EXISTS idx_items_subject_topic ON items(subject, topic);

CREATE TABLE IF NOT EXISTS topics (
  id            TEXT NOT NULL,
  subject       TEXT NOT NULL,
  name          TEXT,
  unit          TEXT,
  ek            TEXT,
  exam_weight_low  REAL,
  exam_weight_high REAL,
  tested_on_exam   INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY (subject, id)
);

CREATE TABLE IF NOT EXISTS teaching (
  topic          TEXT NOT NULL,
  subject        TEXT NOT NULL,
  plain_idea     TEXT,
  worked_example TEXT,
  common_mistake TEXT,
  source_file    TEXT,
  PRIMARY KEY (subject, topic)
);

-- What the server handed out, and when. This is what makes it impossible for the
-- model to fabricate an item id or invent an elapsed time.
CREATE TABLE IF NOT EXISTS serves (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  subject    TEXT NOT NULL,
  item_id    TEXT NOT NULL,
  served_at  TEXT NOT NULL,
  mock_id    INTEGER,
  logged     INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_serves_open ON serves(subject, logged, id);

-- One row per answer. THE source of every number in the system.
CREATE TABLE IF NOT EXISTS attempts (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  ts         TEXT NOT NULL,             -- server clock
  subject    TEXT NOT NULL,
  item_id    TEXT NOT NULL,
  topic      TEXT,
  unit       TEXT,
  practice   TEXT,
  response   TEXT,
  correct    INTEGER NOT NULL,
  picked     TEXT,                      -- for an mcq, the option letter the answer RESOLVED to, as
                                         -- grade.js read it. The distractor is the misconception: 'D'
                                         -- on a short-circuit question is a different error from 'A'
                                         -- on the same question, and `response` (what he typed) does
                                         -- not carry it, because reading it back would depend on
                                         -- whatever the grader's parsing rules are by then. NULL
                                         -- whenever there was no option to record: a blank, a
                                         -- response no grader could read as one answer, an unkeyed
                                         -- item, model-graded work, or any non-mcq item.
                                         -- Added after the table shipped — see the migration note at
                                         -- the top of this file.
  graded_by  TEXT NOT NULL,             -- 'server' (mechanical verdict) | 'model' (rubric-scored FRQ,
                                         -- quarantined from readiness) | 'unkeyed' (item has no usable
                                         -- answer key) | 'unparsed' (response could not be read as one
                                         -- answer) -- see isServerGraded() in grade.js, the only place
                                         -- that may treat one of these as a countable verdict
  seconds    INTEGER,                   -- server measured
  hints_used INTEGER NOT NULL DEFAULT 0,
  conditions TEXT NOT NULL,             -- cold | tutored | proctored_mock
  mock_id    INTEGER
);
CREATE INDEX IF NOT EXISTS idx_attempts_subject ON attempts(subject, ts);
CREATE INDEX IF NOT EXISTS idx_attempts_topic ON attempts(subject, topic);
CREATE INDEX IF NOT EXISTS idx_attempts_mock ON attempts(mock_id);

-- A proctored sitting. Only attempts tied to one of these can move readiness.
CREATE TABLE IF NOT EXISTS mocks (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  subject       TEXT NOT NULL,
  section       TEXT,                   -- 'I' | 'II' | 'full'
  started_at    TEXT NOT NULL,
  ended_at      TEXT,
  proctored     INTEGER NOT NULL DEFAULT 0,
  source        TEXT NOT NULL DEFAULT 'bank',   -- bank | official
  composite_pct REAL,
  blanks        INTEGER
);
CREATE INDEX IF NOT EXISTS idx_mocks_subject ON mocks(subject, started_at);

-- Teaching gaps the server has ordered, and whether the lesson has been given
-- and then re-tested cold. A gap clears only on an unaided correct answer.
CREATE TABLE IF NOT EXISTS gaps (
  subject    TEXT NOT NULL,
  topic      TEXT NOT NULL,
  opened_at  TEXT NOT NULL,
  taught_at  TEXT,
  cleared_at TEXT,
  PRIMARY KEY (subject, topic, opened_at)
);


INSERT OR REPLACE INTO topics (id, subject, name, unit, ek, exam_weight_low, exam_weight_high, tested_on_exam) VALUES
  ('1.1', 'ap_csa', 'Algorithms, Compilers & Error Types', '1', 'Types of errors: syntax (compile-time), logic, run-time, exception; algorithms as step-by-step instructions', 15, 25, 1),
  ('1.2', 'ap_csa', '`int`/`double`/`boolean`, Variables', '1', 'Three primitive types; variable declaration and assignment; literals; naming rules', 15, 25, 1),
  ('1.3', 'ap_csa', 'Arithmetic, Operators & Expressions', '1', 'Output with `System.out.print`/`println`; string/char literals and escapes (`\"` `\\` `\n`); `+ - * / %`; **integer division truncates**; **modulo** semantics; operator precedence; `int ÷ 0` → `ArithmeticException`', 15, 25, 1),
  ('1.4', 'ap_csa', 'Assignment & `null`', '1', '`=` assignment; variable must be initialized before use; `null` as reference literal', 15, 25, 1),
  ('1.5', 'ap_csa', 'Casting, Overflow & Extreme Values', '1', '`(int)` / `(double)` casts; truncation vs rounding `(int)(x + 0.5)`; `Integer.MIN_VALUE` / `Integer.MAX_VALUE`; **integer overflow** wrap-around', 15, 25, 1),
  ('1.6', 'ap_csa', 'Compound Assignment & Post-Increment', '1', '`+= -= *= /= %=`; post-increment `x++` / post-decrement `x--`; value returned is original', 15, 25, 1),
  ('1.7', 'ap_csa', 'APIs, Libraries & Packages', '1', 'Concept of API; library/package import; attributes (state) vs behaviors (methods)', 15, 25, 1),
  ('1.8', 'ap_csa', 'Comments, Pre/Postconditions', '1', '`//`, `/* */`, `/** */`; **preconditions** (assumed true on entry) and **postconditions** (guaranteed on return)', 15, 25, 1),
  ('1.9', 'ap_csa', 'Method Signatures, void/non-void, Call-by-Value, Overloading', '1', 'Method signature (name + param types); void vs return-type; args passed **by value** (copy); **overloading** = same name, different params; flow of control through method calls', 15, 25, 1),
  ('1.10', 'ap_csa', '`static` Class Methods & Dot Operator', '1', '`static` methods belong to class not instance; call via `ClassName.method()`; dot operator', 15, 25, 1),
  ('1.11', 'ap_csa', '`Math` Methods & `random()` Range', '1', '`Math.abs`, `Math.pow`, `Math.sqrt`, `Math.random` [0.0, 1.0); range manipulation: `(int)(Math.random() * n)` → [0, n−1]', 15, 25, 1),
  ('1.12', 'ap_csa', 'Objects, Classes & References', '1', 'Object vs class distinction; reference variables; **all classes extend `Object`** (inherit `toString`, `equals`)', 15, 25, 1),
  ('1.13', 'ap_csa', 'Constructors & `new`', '1', 'Constructor syntax; `new`; overloaded constructors; object initialization', 15, 25, 1),
  ('1.14', 'ap_csa', 'Instance Methods & `NullPointerException`', '1', 'Calling instance methods; **`NullPointerException`** when method called on `null` reference', 15, 25, 1),
  ('1.15', 'ap_csa', '`String`: Immutability, Concatenation & Methods', '1', 'Immutable; `+` concatenation; 0-based indexing; `StringIndexOutOfBoundsException`; 8 String methods (see §2)', 15, 25, 1),
  ('2.1', 'ap_csa', 'Sequencing, Selection, Repetition', '2', 'Three control flow categories; sequential execution', 25, 35, 1),
  ('2.2', 'ap_csa', 'Relational Operators', '2', '`== != < > <= >=`; comparing **primitives** (value) vs **references** (address); do not use `==` on Strings', 25, 35, 1),
  ('2.3', 'ap_csa', '`if` / `if-else`', '2', 'Syntax; one- and two-way selection; boolean test', 25, 35, 1),
  ('2.4', 'ap_csa', 'Nested `if` & `if-else-if` Chains', '2', 'Multi-way selection; boundary conditions; nested `if` inside `if-else`', 25, 35, 1),
  ('2.5', 'ap_csa', '`!` `&&` `||`, Precedence & Short-Circuit', '2', 'Logical NOT/AND/OR; precedence (`!` > `&&` > `||`); **short-circuit evaluation** stops early', 25, 35, 1),
  ('2.6', 'ap_csa', 'Boolean Equivalence, De Morgan & `equals`', '2', 'Truth tables; **De Morgan''s laws** (`!(A&&B)` = `(!A||!B)`); `==` compares references; use `.equals()` for String/object content; `null` check', 25, 35, 1),
  ('2.7', 'ap_csa', '`while` Loop & Off-by-One', '2', '`while` syntax; loop body; infinite loop risk; **off-by-one** boundary errors', 25, 35, 1),
  ('2.8', 'ap_csa', '`for` Loop: Init/Condition/Update & while Equivalence', '2', '`for` loop anatomy; converting `for` ↔ `while`; loop variable scope', 25, 35, 1),
  ('2.9', 'ap_csa', 'Standard Iteration Algorithms', '2', 'Divisibility test, digit extraction, count occurrences, find min/max, accumulate sum/average', 25, 35, 1),
  ('2.10', 'ap_csa', 'String Iteration Algorithms', '2', 'Traverse with `substring`; count substrings; reverse a string; **substring property** (len = to − from)', 25, 35, 1),
  ('2.11', 'ap_csa', 'Nested Loops', '2', 'Nested iteration over 2D-like structures; tracing row-column patterns', 25, 35, 1),
  ('2.12', 'ap_csa', 'Informal Runtime / Statement Execution Count', '2', 'Count how many times a statement executes; compare loop structures (linear vs quadratic); no Big-O notation required', 25, 35, 1),
  ('3.1', 'ap_csa', 'Abstraction, Attributes vs Behaviors, Code Reuse', '3', 'Data abstraction vs procedural abstraction; instance var vs class var; **code reuse via methods + parameters**', 10, 18, 1),
  ('3.2', 'ap_csa', 'Impact, Ethics & IP', '3', '**Reliability, unintended consequences, harm**; intellectual property; open-source permissions', 10, 18, 1),
  ('3.3', 'ap_csa', 'Encapsulation', '3', 'Classes and constructors always `public`; instance variables `private`; hiding implementation details', 10, 18, 1),
  ('3.4', 'ap_csa', 'Constructors, Default Values & Defensive Copies', '3', 'Constructors initialize **all** instance vars; **defensive copy of mutable parameters**; default constructor; default values (`0`, `0.0`, `false`, `null`)', 10, 18, 1),
  ('3.5', 'ap_csa', 'void/non-void Methods, Accessors & Mutators', '3', 'Return-by-value; **accessor** = non-void (returns a value without changing state); **mutator** = void (modifies state); primitive args copied', 10, 18, 1),
  ('3.6', 'ap_csa', 'Object-Reference Params, Aliases & Private Access', '3', '**Object-reference params create aliases**; mutating through a parameter changes the original; returning a reference; **`private` members accessible only within the same class**', 10, 18, 1),
  ('3.7', 'ap_csa', '`static` Variables/Methods & `final`', '3', 'Class (static) vars/methods vs instance; rules for calling static from instance and vice versa; `final` = cannot reassign', 10, 18, 1),
  ('3.8', 'ap_csa', 'Scope, Local Variables & Shadowing', '3', 'Local vars and params have no access modifier; **shadowing** when a local name matches an instance var', 10, 18, 1),
  ('3.9', 'ap_csa', '`this` Keyword', '3', '`this` refers to the current object; disambiguation from shadowed fields; **no `this` in static context**', 10, 18, 1),
  ('4.1', 'ap_csa', 'Ethics: Privacy, Algorithmic Bias & Data Fitness', '4', 'Privacy risks of data collection; **algorithmic bias**; fitness of data for a purpose', 30, 40, 1),
  ('4.2', 'ap_csa', 'Data Sets & One-at-a-Time Access', '4', 'Concept of a data set; accessing elements sequentially', 30, 40, 1),
  ('4.3', 'ap_csa', 'Array Creation, `length` Attribute & Defaults', '4', '`new type[n]`; **`arr.length` is an attribute (not a method)**; default values; initializer list `{...}`; `[]` syntax; valid indices 0..length−1; `ArrayIndexOutOfBoundsException`', 30, 40, 1),
  ('4.4', 'ap_csa', 'Array Traversal: Indexed vs Enhanced-for', '4', 'Index-based `for`; **enhanced-for copies the element (primitive copy; object reference copy)**; method call on an object element mutates the object', 30, 40, 1);
INSERT OR REPLACE INTO topics (id, subject, name, unit, ek, exam_weight_low, exam_weight_high, tested_on_exam) VALUES
  ('4.5', 'ap_csa', 'Standard Array Algorithms (9)', '4', 'Max/min, sum/average, count, linear search, reverse in place, shift elements, copy array, replace elements, sort', 30, 40, 1),
  ('4.6', 'ap_csa', 'Text Files: `File` + `Scanner`, `split`, `close`', '4', '`File(String)` + `Scanner(File)`; `throws IOException`; `java.io` import; **`hasNext()` loop**; `split(String del)` to parse columns; `close()`; no keyboard `Scanner`; no `nextLine` mixed with token methods; no regex in `split`', 30, 40, 1),
  ('4.7', 'ap_csa', 'Wrapper Classes: `Integer`, `Double`, Autoboxing', '4', '`Integer` / `Double` are **immutable**; **autoboxing** (primitive → wrapper) / **unboxing** (wrapper → primitive); `Integer.parseInt(String)`, `Double.parseDouble(String)`', 30, 40, 1),
  ('4.8', 'ap_csa', '`ArrayList<E>`: Creation & 6 Methods', '4', '`ArrayList<E>`; mutable size; `java.util` import; 6 methods (see §2); valid indices 0..size−1', 30, 40, 1),
  ('4.9', 'ap_csa', 'ArrayList Traversal & Modification Pitfalls', '4', 'Index-based and enhanced-for traversal; **delete-while-traversing: iterate backwards or use index adjustment**; `IndexOutOfBoundsException`; **enhanced-for + structural modify → `ConcurrentModificationException`**', 30, 40, 1),
  ('4.10', 'ap_csa', 'ArrayList Algorithms (11)', '4', '9 standard algorithms + insert-in-order + delete-by-condition; multi-structure simultaneous traversal', 30, 40, 1),
  ('4.11', 'ap_csa', '2D Arrays: Structure & Indexing', '4', 'Array-of-arrays; `[row][col]` syntax; `a.length` = number of rows; `a[0].length` = number of columns; **no jagged arrays**', 30, 40, 1),
  ('4.12', 'ap_csa', '2D Array Traversal: Row-Major, Col-Major & Enhanced-for', '4', 'Nested loops for row-major / col-major / custom order; **enhanced-for outer variable = a 1D array (one row)**', 30, 40, 1),
  ('4.13', 'ap_csa', '2D Array Algorithms', '4', 'Over whole array, individual row, individual column, or sub-section; sum, count, find max/min in 2D', 30, 40, 1),
  ('4.14', 'ap_csa', 'Linear Search', '4', 'Sequential scan from either end; returning index or -1 / element; 2D = linear search per row', 30, 40, 1),
  ('4.15', 'ap_csa', 'Selection Sort & Insertion Sort (Trace)', '4', 'Selection: find min of unsorted segment, swap to front; insertion: insert next element into sorted prefix; **trace-only — writing sort code is out of scope**', 30, 40, 1),
  ('4.16', 'ap_csa', 'Recursion (Trace Only)', '4', 'Base case; recursive case; each call has its own local variables; trace the call stack; **writing recursive code is out of scope**', 30, 40, 1),
  ('4.17', 'ap_csa', 'Binary Search & Merge Sort (Trace)', '4', 'Binary search: sorted array, halve the search space each step; merge sort: recursive divide-and-merge; both **trace-only**', 30, 40, 1),
  ('1.1', 'ap_precalc', 'Average Rate of Change (AROC) + the secant line', '1', 'AROC over [a, b] is the slope of the straight line (secant) connecting the two endpoints on the graph. It''s "rise over run" for a function.', 30, 40, 1),
  ('1.2', 'ap_precalc', 'Concavity + how AROC changes (the FRQ favorite)', '1', 'Concavity tells you whether the *rate of change itself* is speeding up or slowing down.
- **Concave UP** (curls upward, like a cup): rate of change is **increasing**.
- **Concave DOWN** (curls over, like a frown): rate of change is **decreasing**.

A secant line on a concave-**down** graph lies **below** the curve between the points → a linear estimate **underestimates** the true value there. (This exact reasoning was Q2(B)(iii) in BOTH 2024 and 2025.)', 30, 40, 1),
  ('1.3', 'ap_precalc', 'Polynomial end behavior (degree + leading term)', '1', 'Far left and far right, a polynomial behaves like its **leading term** $a_nx^n$ only.', 30, 40, 1),
  ('1.4', 'ap_precalc', 'Real & complex zeros + multiplicity', '1', 'A zero is where $f(x)=0$ (an x-intercept if real). **Multiplicity** = how many times that factor repeats, and it controls how the graph behaves at that x-intercept.
- **Odd multiplicity** (1, 3, …): graph **crosses** the x-axis.
- **Even multiplicity** (2, 4, …): graph **touches and bounces** (tangent to axis).

A degree-$n$ polynomial has exactly $n$ zeros counting multiplicity and complex ones. **Complex (non-real) zeros come in conjugate pairs** ($a+bi$ with $a-bi$).', 30, 40, 1),
  ('1.5', 'ap_precalc', 'Even / odd functions (symmetry)', '1', '- **Even:** $f(-x)=f(x)$ → symmetric about the **y-axis** (e.g., $x^2$, $\cos$). Even-power terms only.
- **Odd:** $f(-x)=-f(x)$ → symmetric about the **origin** (e.g., $x^3$, $\sin$). Odd-power terms only.', 30, 40, 1),
  ('1.6', 'ap_precalc', 'Rational functions — vertical asymptotes & holes', '1', 'Factor top and bottom first.
- **Hole (removable):** a factor that cancels from both numerator and denominator. The hole is at that x-value.
- **Vertical asymptote (VA):** a factor in the denominator that does **NOT** cancel. Output → ±∞ there.', 30, 40, 1),
  ('1.7', 'ap_precalc', 'Rational functions — horizontal & slant asymptotes + domain', '1', 'Compare the degrees of numerator (N) and denominator (D):
- **deg N < deg D** → horizontal asymptote **y = 0**.
- **deg N = deg D** → horizontal asymptote **y = ratio of leading coefficients**.
- **deg N = deg D + 1** → **slant (oblique) asymptote**; do polynomial long division, the quotient (drop remainder) is the line.
- **deg N > deg D + 1** → no horizontal/slant asymptote (end behavior follows the quotient polynomial).', 30, 40, 1),
  ('1.8', 'ap_precalc', 'Equivalent representations (factored ↔ standard) + building/applying models', '1', 'Same function, different forms for different jobs:
- **Factored form** reveals **zeros** instantly: $f(x)=2(x-3)(x+1)$.
- **Standard form** reveals **end behavior / leading coefficient / y-intercept**: $f(x)=2x^2-4x-6$.', 30, 40, 1),
  ('1.9', 'ap_precalc', 'Transformations of functions', '1', 'Starting from $f(x)$, build $g(x)=a\,f(b(x-h))+k$:
- **k**: vertical shift (up if +).
- **h**: horizontal shift (RIGHT if $x-h$ with +h — opposite of intuition).
- **a**: vertical stretch (|a|>1) / compress; reflect over x-axis if a<0.
- **b**: horizontal stretch/compress by 1/|b|; reflect over y-axis if b<0.', 30, 40, 1),
  ('1.10', 'ap_precalc', 'Piecewise-defined functions *(easy to skip — and it''s a named FRQ2 model type)*', '1', 'A **piecewise function** is built from different rules on **non-overlapping** intervals of the domain — one formula here, a different one there.', 30, 40, 1),
  ('1.11', 'ap_precalc', 'Model domain & range restrictions *(FRQ Q2 Part C points)*', '1', 'Model domain & range restrictions *(FRQ Q2 Part C points)*', 30, 40, 1),
  ('2.1', 'ap_precalc', 'Arithmetic vs. Geometric Sequences', '2', 'A sequence is a list of numbers following a rule. **Arithmetic** = you *add* the same number each step (constant difference). **Geometric** = you *multiply* by the same number each step (constant ratio). Arithmetic ↔ linear; geometric ↔ exponential.', 25, 40, 1),
  ('2.2', 'ap_precalc', 'Linear vs. Exponential Change (the core distinction)', '2', 'Linear functions change by a **constant amount** over equal-length input intervals (add the same thing). Exponential functions change by a **constant proportion/ratio** (multiply by the same factor). This is the #1 conceptual idea the exam tests — including FRQ Q1 2025, which asked students to identify a table as exponential by checking ratios.', 25, 40, 1),
  ('2.3', 'ap_precalc', 'Exponential Functions: Growth, Decay, Base, Transformations', '2', '$f(x) = a\cdot b^{x}$. Here $a$ = initial value (y-intercept, the value at $x=0$), $b$ = base = the growth/decay factor. $b>1$ → **growth**; $0<b<1$ → **decay**. The graph has a **horizontal asymptote** (default $y=0$).', 25, 40, 1),
  ('2.4', 'ap_precalc', 'Function Composition', '2', '$(f\circ g)(x) = f(g(x))$ — do the **inside first**, feed its output into the outside function. Order matters; $f(g(x)) \neq g(f(x))$ in general.', 25, 40, 1),
  ('2.5', 'ap_precalc', 'Inverse Functions', '2', 'The inverse $f^{-1}$ undoes $f$: it swaps inputs and outputs. If $(a,b)$ is on $f$, then $(b,a)$ is on $f^{-1}$. A function has an inverse only if it''s **one-to-one** (passes the horizontal line test). To find it algebraically: swap $x$ and $y$, solve for $y$.', 25, 40, 1),
  ('2.6', 'ap_precalc', 'Logarithmic Functions & Graphs', '2', 'A log answers "what exponent?" $\log_b x = y$ means $b^y = x$. It''s the inverse of $b^x$. $\log$ (no base) = base 10; $\ln$ = base $e$.', 25, 40, 1),
  ('2.7', 'ap_precalc', 'Properties / Rules of Logs (the FRQ Q4 bread-and-butter)', '2', 'Three rules turn products into sums, quotients into differences, and exponents into coefficients. Used to **condense** to a single log or **expand** — both directions appear on FRQ Q4.', 25, 40, 1),
  ('2.8', 'ap_precalc', 'Solving Exponential & Logarithmic Equations', '2', 'To solve for a variable in an exponent, take a log of both sides. To solve a log equation, exponentiate (rewrite in exponential form) — then **check for extraneous solutions** (domain!).', 25, 40, 1),
  ('2.9', 'ap_precalc', 'Exponential & Logarithmic Modeling', '2', 'Fit a model to data/context, then use it to predict or interpret. **Exponential model** $y=ab^t$ when there''s a constant percent rate. **Logarithmic model** $y=a+b\ln(t+c)$ when growth is fast-then-leveling. This is FRQ Q2 territory (the second-hardest FRQ).', 25, 40, 1),
  ('2.10', 'ap_precalc', 'Semi-Log Plots (Linearizing Data)', '2', 'A **semi-log plot** puts the y-axis on a **log scale** (and x linear). On this plot, **exponential data becomes a straight line.** That''s the whole point: it''s a visual test for "is this exponential?"

> **Exam scope (important):** On the AP exam, semi-log means the **log scale is on the y-axis ONLY, to linearize EXPONENTIAL data.** Putting the *x*-axis on a log scale (to linearize logarithmic data) and full **log-log** plots are **OUT of scope** — don''t study them. The exam writes the linearized form as $y=(\log_n b)x+\log_n a$ for a log base $n>1$.', 25, 40, 1),
  ('2.11', 'ap_precalc', 'Model Error & Residuals (EK 2.6.B — easy points the exam likes)', '2', 'Once you fit a model, you judge how good it is.
- **Error (residual)** at a point = **predicted − actual** value. Positive error = the model **overestimates** there; negative = **underestimates**.
- **Residual plot test:** a model is **appropriate only if the residual plot has NO pattern** (points scattered randomly around 0). A clear pattern (curve, fan shape) means the model type is wrong. *(This is a classic MCQ.)*
- **Context can make an over- or under-estimate preferable.** The exam may ask which is "better" for a situation — e.g., for ordering enough supplies, an **overestimate** is safer; there isn''t a universal "right" choice, it depends on the scenario. Justify with the context.', 25, 40, 1),
  ('3.1', 'ap_precalc', 'Radians & the unit circle (the foundation — memorize cold)', '3', 'A radian measures angle by arc length on a circle of radius 1. Once around = 2π radians = 360°. On the unit circle, the point at angle θ is **(cos θ, sin θ)**.', 30, 35, 1),
  ('3.2', 'ap_precalc', 'Sinusoidal functions: amplitude, period, midline, phase shift', '3', 'Sine and cosine make repeating "waves." Four numbers fully describe any wave.', 30, 35, 1),
  ('3.3', 'ap_precalc', 'The five key points + midline, over TWO cycles (FRQ Q3 **Part A** — scorable points you can''t skip)', '3', 'The five key points + midline, over TWO cycles (FRQ Q3 **Part A** — scorable points you can''t skip)', 30, 35, 1),
  ('3.4', 'ap_precalc', 'Sinusoidal behavior on an interval + concavity ↔ rate of change (FRQ Q3 gold)', '3', 'On any piece of a wave the exam asks two things: is the function **positive/negative** and **increasing/decreasing**, AND is the **rate of change increasing or decreasing** (concavity — no calculus needed, just read the curve).', 30, 35, 1),
  ('3.5', 'ap_precalc', 'The tangent function', '3', 'tan θ = sin θ/cos θ. It has **no amplitude**, repeats every **π** (not 2π), and shoots to ±∞ (vertical asymptotes) where cos = 0.', 30, 35, 1);
INSERT OR REPLACE INTO topics (id, subject, name, unit, ek, exam_weight_low, exam_weight_high, tested_on_exam) VALUES
  ('3.6', 'ap_precalc', 'Inverse trig functions (and their restricted ranges)', '3', 'arcsin/arccos/arctan undo trig, but only on a restricted piece so the answer is unique. **The range restriction is the whole game.**', 30, 35, 1),
  ('3.7', 'ap_precalc', 'Solving trig equations', '3', 'Find ALL angles that work, not just the one the calculator/unit circle hands you. Sine/cosine repeat every 2π; tangent every π.', 30, 35, 1),
  ('3.8', 'ap_precalc', 'Secant, cosecant, cotangent (reciprocals)', '3', 'Just flips. **sec = 1/cos, csc = 1/sin, cot = 1/tan = cos/sin.**', 30, 35, 1),
  ('3.9', 'ap_precalc', 'Trig identities (Pythagorean, sum/difference, double-angle)', '3', 'Algebra rewrite rules. The exam''s #1 use: simplify a messy expression to "a single term" or solve an equation by substituting an identity.', 30, 35, 1),
  ('3.10', 'ap_precalc', 'Polar coordinates & polar graphs', '3', 'Locate a point by **distance r from origin and angle θ**, instead of (x, y). A polar function r = f(θ) traces a curve as θ sweeps around.', 30, 35, 1),
  ('3.11', 'ap_precalc', 'Rates of change in polar functions', '3', 'As θ increases, watch whether **r (distance from origin) grows or shrinks**, and how fast. The exam asks this verbally — "is the distance from the origin increasing?" — and via average rate of change of r.', 30, 35, 1),
  ('4.1', 'ap_precalc', 'Parametric functions', '4', 'Instead of `y = f(x)`, both `x` and `y` are written in terms of a third variable `t` (often "time"): `x = f(t)`, `y = g(t)`. As `t` increases, the point `(x, y)` traces a path — this captures **direction and timing**, which a plain `y = f(x)` can''t.', 0, 0, 0),
  ('4.2', 'ap_precalc', 'Parametric rates of change (concept only, no derivatives needed)', '4', 'In a parametric path, `x` and `y` each change as `t` changes. Compare their **average rates of change over a `t`-interval**.', 0, 0, 0),
  ('4.3', 'ap_precalc', 'Parametric circles & lines (memorize these templates)', '4', 'Parametric circles & lines (memorize these templates)', 0, 0, 0),
  ('4.4', 'ap_precalc', 'Implicitly defined functions', '4', 'An equation like `x² + y² = 25` defines a relationship between `x` and `y` without `y` being isolated. It may **fail the vertical line test** (not a function), so you often split it into pieces.', 0, 0, 0),
  ('4.5', 'ap_precalc', 'Conic sections (the formula table — memorize)', '4', 'Curves you get from slicing a cone: circle, ellipse, parabola, hyperbola. You identify them from their standard-form equations.

| Conic | Standard form (centered at `(h,k)`) | Tell-tale sign |
|---|---|---|
| **Circle** | `(x−h)² + (y−k)² = r²` | both squared, **same coeff**, `+` |
| **Ellipse** | `(x−h)²/a² + (y−k)²/b² = 1` | both squared, **different** coeffs, **same sign**, `+` |
| **Parabola** | `y = a(x−h)² + k` (or `x = a(y−k)²+h`) | **only one** variable squared |
| **Hyperbola** | `(x−h)²/a² − (y−k)²/b² = 1` | both squared, **opposite signs** (a `−`) |', 0, 0, 0),
  ('4.6', 'ap_precalc', 'Vectors', '4', 'A vector has **magnitude (length) and direction**. Written in components `⟨a, b⟩` (from initial to terminal point).', 0, 0, 0),
  ('4.7', 'ap_precalc', 'Vector-valued functions', '4', 'A function whose **output is a vector** that changes with `t`: `p(t) = ⟨x(t), y(t)⟩`. This is just the parametric idea written in vector form — the position of a moving object at time `t`.', 0, 0, 0),
  ('4.8', 'ap_precalc', 'Matrices: operations', '4', 'A rectangular grid of numbers. Add/subtract entry-by-entry; multiply rows-by-columns.', 0, 0, 0),
  ('4.9', 'ap_precalc', 'Determinant & inverse of a 2×2 matrix', '4', 'Determinant & inverse of a 2×2 matrix', 0, 0, 0),
  ('4.10', 'ap_precalc', 'Linear transformations & matrices as functions', '4', 'A 2×2 matrix can act as a **function** that takes an input vector and outputs a transformed vector: `A·v`. Geometrically it rotates / scales / reflects / shears the plane. The **determinant = area scaling factor** (and a negative det means orientation flips).', 0, 0, 0),
  ('4.11', 'ap_precalc', 'Matrices modeling contexts (transition / Leslie-style)', '4', 'A matrix can encode how a system moves between states each step (e.g., population, market share). Multiply the **state vector** by the **transition matrix** to advance one step; multiply repeatedly (or use `Aⁿ`) for `n` steps.', 0, 0, 0);

INSERT OR REPLACE INTO items (id, subject, topic, unit, practice, kind, stem, options_json, answer, answer_variants_json, explanation, rubric_json, difficulty, calc_allowed) VALUES
  ('csa-ac-q1', 'ap_csa', '1.3', '1', 'P3', 'mcq', 'What is printed?
```java
int a = 17, b = 5;
System.out.println(a / b + "." + a % b);
```', '{"A":"3.4","B":"3.0","C":"3.2","D":"4.2"}', 'C', NULL, 'Integer division `17 / 5 = 3`; `17 % 5 = 2`; concatenated with `"."` (string mode once a String appears) → `"3.2"`.', NULL, NULL, NULL),
  ('csa-ac-q2', 'ap_csa', '1.3', '1', 'P3', 'mcq', 'What is printed?
```java
System.out.println(2 + 3 * 4 - 10 / 3);
```', '{"A":"11","B":"12","C":"9","D":"7"}', 'A', NULL, '`*` and `/` bind first: `3*4 = 12`, `10/3 = 3` (integer). Then `2 + 12 - 3 = 11`.', NULL, NULL, NULL),
  ('csa-ac-q3', 'ap_csa', '1.3', '1', 'P3', 'mcq', 'What is printed?
```java
System.out.println(1 + 2 + "x" + 1 + 2);
```', '{"A":"3x3","B":"12x12","C":"1212x","D":"3x12"}', 'D', NULL, 'Evaluated left to right: `1+2 = 3` (still ints), then `3 + "x" = "3x"`, then `"3x"+1 = "3x1"`, `+2 = "3x12"`.', NULL, NULL, NULL),
  ('csa-ac-q4', 'ap_csa', '1.3', '1', 'P3', 'mcq', 'What is the result of running this segment?
```java
int x = 8, y = 0;
System.out.println(x / y);
```', '{"A":"0","B":"8","C":"The program throws an `ArithmeticException`.","D":"It prints `Infinity`."}', 'C', NULL, 'Integer division by zero throws `ArithmeticException` at runtime before anything prints. (`Infinity` only arises from `double` division like `8.0 / 0.0`, not integer division.)', NULL, NULL, NULL),
  ('csa-ac-q5', 'ap_csa', '1.5', '1', 'P3', 'mcq', 'What is printed?
```java
double d = 9.99;
System.out.println((int) d);
```', '{"A":"10","B":"9","C":"9.99","D":"9.0"}', 'B', NULL, '`(int)` **truncates** toward zero (it does not round): `9.99 → 9`.', NULL, NULL, NULL),
  ('csa-ac-q6', 'ap_csa', '1.5', '1', 'P3', 'mcq', 'What is printed?
```java
double price = 4.5;
int rounded = (int)(price + 0.5);
System.out.println(rounded);
```', '{"A":"4","B":"4.5","C":"5","D":"5.0"}', 'C', NULL, '`4.5 + 0.5 = 5.0`; `(int)` truncates `5.0 → 5`. The `+0.5`-then-truncate idiom rounds to nearest; the result is an `int`, so no decimal point.', NULL, NULL, NULL),
  ('csa-ac-q7', 'ap_csa', '1.5', '1', 'P3', 'mcq', 'What is printed?
```java
int a = 7, b = 2;
System.out.println((double) a / b);
```', '{"A":"3.0","B":"3.5","C":"3","D":"4.0"}', 'B', NULL, 'The cast applies to `a` first → `7.0`, then `7.0 / 2` is **double** division = `3.5`. (Contrast `(double)(a / b)`, which truncates first → `3.0`.)', NULL, NULL, NULL),
  ('csa-ac-q8', 'ap_csa', '1.5', '1', 'P3', 'mcq', 'What is printed?
```java
int big = Integer.MAX_VALUE;
System.out.println(big + 1);
```', '{"A":"2147483648","B":"Integer.MAX_VALUE","C":"-2147483648","D":"0"}', 'C', NULL, 'Adding 1 to `Integer.MAX_VALUE` **overflows** and wraps to `Integer.MIN_VALUE` = `-2147483648`. No exception is thrown for overflow, and it does not saturate at the max or reset to `0`.', NULL, NULL, NULL),
  ('csa-ac-q9', 'ap_csa', '1.6', '1', 'P3', 'mcq', 'What is printed?
```java
int x = 5;
int y = x++;
System.out.println(x + " " + y);
```', '{"A":"6 5","B":"6 6","C":"5 6","D":"5 5"}', 'A', NULL, '`x++` returns the **original** value (5) to `y`, then increments `x` to 6. So `x` is 6, `y` is 5.', NULL, NULL, NULL),
  ('csa-ac-q10', 'ap_csa', '1.6', '1', 'P3', 'mcq', 'What is printed?
```java
int n = 20;
n -= 3;
n *= 2;
n %= 7;
System.out.println(n);
```', '{"A":"34","B":"5","C":"0","D":"6"}', 'D', NULL, '`20 - 3 = 17`; `17 * 2 = 34`; `34 % 7 = 6` (34 = 4·7 + 6).', NULL, NULL, NULL),
  ('csa-ac-q11', 'ap_csa', '1.11', '1', 'P3', 'mcq', 'What is printed?
```java
System.out.println(Math.pow(2, 5));
```', '{"A":"32","B":"10.0","C":"32.0","D":"25.0"}', 'C', NULL, '`Math.pow(2, 5)` returns a **double**, `2^5 = 32.0` (printed with the decimal point).', NULL, NULL, NULL),
  ('csa-ac-q12', 'ap_csa', '1.11', '1', 'P3', 'mcq', 'What is printed?
```java
System.out.println(Math.abs(-9) + (int) Math.sqrt(20));
```', '{"A":"14","B":"9","C":"13.0","D":"13"}', 'D', NULL, '`Math.abs(-9) = 9` (int overload). `Math.sqrt(20) ≈ 4.47`, cast to `int` truncates to `4`. `9 + 4 = 13`.', NULL, NULL, NULL),
  ('csa-ac-q13', 'ap_csa', '1.11', '1', 'P3', 'mcq', 'Which expression produces a random integer in the range **5 to 10 inclusive**?
```java
// Math.random() returns a double in [0.0, 1.0)
```', '{"A":"(int)(Math.random() * 10) + 5","B":"(int)(Math.random() * 6) + 5","C":"(int)(Math.random() * 5) + 10","D":"(int)(Math.random() * 11)"}', 'B', NULL, '`(int)(Math.random()*6)` yields `0..5`; adding 5 shifts to `5..10` (6 values, inclusive). This is a trace of the standard range formula `(int)(Math.random()*count) + min`.', NULL, NULL, NULL),
  ('csa-ac-q14', 'ap_csa', '2.5', '2', 'P3', 'mcq', 'What is printed?
```java
int x = 4, y = 0;
if (y != 0 && x / y > 1) {
    System.out.println("A");
} else {
    System.out.println("B");
}
```', '{"A":"A","B":"An `ArithmeticException` is thrown.","C":"B","D":"Nothing."}', 'C', NULL, '`y != 0` is `false`, so `&&` **short-circuits**: `x / y` is never evaluated, no exception. The `else` prints `B`.', NULL, NULL, NULL),
  ('csa-ac-q15', 'ap_csa', '2.5', '2', 'P3', 'mcq', 'How many times does `check()` run?
```java
boolean b = true;
if (b || check()) {
    System.out.println("done");
}
// check() prints nothing relevant; question is how many times it is called
```', '{"A":"1","B":"2","C":"3","D":"0"}', 'D', NULL, '`true || ...` short-circuits — once the left side is `true`, the right operand `check()` is **never called**. (A) is the count if you think `||` always evaluates the right side; (B) double-counts a re-evaluation when the body runs; (C) imagines the `if` re-polls `check()` until it settles.', NULL, NULL, NULL),
  ('csa-ac-q16', 'ap_csa', '2.5', '2', 'P3', 'mcq', 'What is the value of `result`?
```java
boolean a = true, b = false, c = true;
boolean result = a || b && !c;
```', '{"A":"true","B":"false","C":"It does not compile — `&&` and `||` cannot be combined without parentheses.","D":"It is unspecified — the result depends on operand evaluation order."}', 'A', NULL, 'Precedence is `!` > `&&` > `||`: `!c = false`; then `b && false = false`; then `a || false = true`. (B) is the wrong-precedence value from grouping left to right as `(a || b) && !c` = `true && false` = `false`; (C) is false — Java fully defines this precedence, so no parentheses are required; (D) is false — operand order is fully specified (left to right), so the result is determinate.', NULL, NULL, NULL),
  ('csa-ac-q17', 'ap_csa', '2.6', '2', 'P3', 'mcq', 'Given `int x`, which expression is **always equal** to `!(x > 0 && x < 10)`?', '{"A":"x <= 0 && x >= 10","B":"x < 0 || x > 10","C":"x <= 0 || x >= 10","D":"!(x > 0) && !(x < 10)"}', 'C', NULL, 'De Morgan: `!(A && B)` = `!A || !B`. `!(x>0)` = `x<=0`, `!(x<10)` = `x>=10`, joined by `||`.', NULL, NULL, NULL),
  ('csa-ac-q18', 'ap_csa', '2.2', '2', 'P3', 'mcq', 'What is printed?
```java
int a = 3, b = 3;
System.out.println(a == b);
```', '{"A":"true","B":"false","C":"Compile error","D":"3"}', 'A', NULL, 'For **primitives**, `==` compares values; `3 == 3` is `true`. (`==` is the value test for primitives — only for *objects* does it compare references.)', NULL, NULL, NULL),
  ('csa-ac-q19', 'ap_csa', '2.6', '2', 'P3', 'mcq', 'What is printed?
```java
String s = "cat";
String t = new String("cat");
System.out.println(s.equals(t) + " " + (s == t));
```', '{"A":"true true","B":"true false","C":"false false","D":"false true"}', 'B', NULL, '`.equals` compares **contents** → `true`; `==` compares **references**, and `new String(...)` is a distinct object → `false`.', NULL, NULL, NULL),
  ('csa-ac-q20', 'ap_csa', '2.4', '2', 'P3', 'mcq', 'What is printed when `n = 5`?
```java
int n = 5;
if (n > 10)      System.out.println("big");
else if (n > 3)  System.out.println("mid");
else if (n > 0)  System.out.println("small");
else             System.out.println("none");
```', '{"A":"big","B":"mid","C":"small","D":"`mid` and `small`"}', 'B', NULL, '`5 > 10` false; `5 > 3` true → prints `mid` and the chain **stops** (later branches are skipped even though `5 > 0` is also true).', NULL, NULL, NULL),
  ('csa-ac-q21', 'ap_csa', '2.4', '2', 'P3', 'mcq', 'What is printed when `x = 8`?
```java
int x = 8;
if (x > 5)
    if (x > 10)
        System.out.println("high");
    else
        System.out.println("mid");
```', '{"A":"high","B":"Nothing.","C":"`high` then `mid`","D":"mid"}', 'D', NULL, 'The `else` binds to the **nearest** `if` (`x > 10`). `x > 5` true, enter; `x > 10` false → the inner `else` runs → `mid`.', NULL, NULL, NULL),
  ('csa-ac-q22', 'ap_csa', '2.7', '2', 'P3', 'mcq', 'What is printed?
```java
int n = 1, count = 0;
while (n < 100) {
    n = n * 2;
    count++;
}
System.out.println(count);
```', '{"A":"6","B":"8","C":"64","D":"7"}', 'D', NULL, 'n: 1→2→4→8→16→32→64→128, one `count++` per step. The loop multiplies 7 times (128 is the first value ≥ 100). `count = 7`.', NULL, NULL, NULL),
  ('csa-ac-q23', 'ap_csa', '2.7', '2', 'P3', 'mcq', 'How many times does the body execute?
```java
int i = 0;
while (i <= 5) {
    System.out.print("*");
    i++;
}
```', '{"A":"5","B":"6","C":"7","D":"Infinite"}', 'B', NULL, '`i` takes 0,1,2,3,4,5 (six values) before `i = 6` fails `i <= 5`. Six stars. (Using `<` would give 5 — the classic off-by-one.)', NULL, NULL, NULL),
  ('csa-ac-q24', 'ap_csa', '2.8', '2', 'P3', 'mcq', 'What is printed?
```java
int sum = 0;
for (int i = 2; i <= 10; i += 2) {
    sum += i;
}
System.out.println(sum);
```', '{"A":"20","B":"30","C":"25","D":"12"}', 'B', NULL, 'i = 2,4,6,8,10; sum = 2+4+6+8+10 = `30`.', NULL, NULL, NULL),
  ('csa-ac-q25', 'ap_csa', '2.8', '2', 'P3', 'mcq', 'What is printed?
```java
int total = 0;
for (int k = 5; k > 0; k--) {
    total += k;
}
System.out.println(total);
```', '{"A":"10","B":"0","C":"15","D":"5"}', 'C', NULL, 'k = 5,4,3,2,1; total = 5+4+3+2+1 = `15`. The decrementing `for` is equivalent to a `while` with `k--` at the bottom.', NULL, NULL, NULL),
  ('csa-ac-q26', 'ap_csa', '2.9', '2', 'P3', 'mcq', 'What is printed?
```java
int n = 4729, sum = 0;
while (n > 0) {
    sum += n % 10;
    n = n / 10;
}
System.out.println(sum);
```', '{"A":"22","B":"4729","C":"9","D":"18"}', 'A', NULL, 'Peels off last digits: 9, 2, 7, 4 → sum = 9+2+7+4 = `22`.', NULL, NULL, NULL),
  ('csa-ac-q27', 'ap_csa', '2.9', '2', 'P3', 'mcq', 'What is printed?
```java
int count = 0;
for (int i = 1; i <= 30; i++) {
    if (i % 4 == 0) count++;
}
System.out.println(count);
```', '{"A":"6","B":"8","C":"4","D":"7"}', 'D', NULL, 'Multiples of 4 in 1..30: 4,8,12,16,20,24,28 → `7`.', NULL, NULL, NULL),
  ('csa-ac-q28', 'ap_csa', '2.9', '2', 'P3', 'mcq', 'What is printed?
```java
int[] data = {3, 9, 2, 9, 7};
int max = data[0];
for (int i = 1; i < data.length; i++) {
    if (data[i] > max) max = data[i];
}
System.out.println(max);
```', '{"A":"7","B":"9","C":"3","D":"2"}', 'B', NULL, 'Standard max scan: starts at 3, updates to 9, stays 9 (the `>` keeps the first 9; either 9 gives the same value). Max = `9`.', NULL, NULL, NULL),
  ('csa-ac-q29', 'ap_csa', '1.15', '1', 'P3', 'mcq', 'What is printed?
```java
String s = "programming";
System.out.println(s.substring(3, 7));
```', '{"A":"ogra","B":"ramm","C":"gram","D":"gramm"}', 'C', NULL, 'Indices 3,4,5,6 (the `to` index 7 is **excluded**). `p(0)r(1)o(2)g(3)r(4)a(5)m(6)` → `gram` (length = 7−3 = 4).', NULL, NULL, NULL),
  ('csa-ac-q30', 'ap_csa', '1.15', '1', 'P3', 'mcq', 'What is printed?
```java
String s = "abcdef";
System.out.println(s.substring(4));
```', '{"A":"def","B":"ef","C":"cdef","D":"e"}', 'B', NULL, '`substring(4)` returns from index 4 to the end: characters at 4 (`e`) and 5 (`f`) → `ef`.', NULL, NULL, NULL),
  ('csa-ac-q31', 'ap_csa', '1.15', '1', 'P3', 'mcq', 'What is printed?
```java
String s = "banana";
System.out.println(s.indexOf("na"));
```', '{"A":"1","B":"2","C":"4","D":"-1"}', 'B', NULL, '`indexOf` returns the **first** occurrence: `b(0)a(1)n(2)a(3)...`, "na" first starts at index 2.', NULL, NULL, NULL),
  ('csa-ac-q32', 'ap_csa', '2.10', '2', 'P3', 'mcq', 'What is printed?
```java
String s = "hello";
String out = "";
for (int i = 0; i < s.length(); i++) {
    out = s.substring(i, i + 1) + out;
}
System.out.println(out);
```', '{"A":"hello","B":"o","C":"h","D":"olleh"}', 'D', NULL, 'Each char (`s.substring(i, i+1)`) is prepended, reversing the string: `olleh`. (This is the in-syllabus reverse algorithm; there is no `charAt`.)', NULL, NULL, NULL),
  ('csa-ac-q33', 'ap_csa', '2.10', '2', 'P3', 'mcq', 'What is the result?
```java
String s = "abc";
System.out.println(s.substring(2, 4));
```', '{"A":"c","B":"bc","C":"An empty string","D":"A `StringIndexOutOfBoundsException` is thrown."}', 'D', NULL, '`s` has length 3 (valid indices 0..2). `substring(2, 4)` needs index up to 3, which is out of range → `StringIndexOutOfBoundsException`.', NULL, NULL, NULL),
  ('csa-ac-q34', 'ap_csa', '2.10', '2', 'P3', 'mcq', 'What is printed?
```java
String csv = "red,green,blue,yellow";
String[] parts = csv.split(",");
System.out.println(parts.length + " " + parts[2]);
```', '{"A":"4 blue","B":"3 blue","C":"4 green","D":"4 yellow"}', 'A', NULL, '`split(",")` on a literal comma gives `["red","green","blue","yellow"]` — length 4; index 2 is `blue`.', NULL, NULL, NULL),
  ('csa-ac-q35', 'ap_csa', '2.11', '2', 'P3', 'mcq', 'What is printed?
```java
int total = 0;
for (int i = 0; i < 5; i++) {
    for (int j = 0; j <= i; j++) {
        total++;
    }
}
System.out.println(total);
```', '{"A":"25","B":"10","C":"20","D":"15"}', 'D', NULL, 'Inner runs i+1 times: 1+2+3+4+5 = `15` (the inner condition is `j <= i`).', NULL, NULL, NULL),
  ('csa-ac-q36', 'ap_csa', '2.11', '2', 'P3', 'mcq', 'What is printed?
```java
for (int r = 1; r <= 3; r++) {
    for (int c = 1; c <= r; c++) {
        System.out.print(c);
    }
    System.out.println();
}
```', '{"A":"`1` / `12` / `123`","B":"`1` / `11` / `111`","C":"`123` / `12` / `1`","D":"`111` / `22` / `3`"}', 'A', NULL, 'Row r prints `1..r`: row1 `1`, row2 `12`, row3 `123` (each on its own line).', NULL, NULL, NULL),
  ('csa-ac-q37', 'ap_csa', '2.12', '2', 'P3', 'mcq', 'How many times does the marked statement execute?
```java
int n = 6;
for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
        System.out.print("*");   // <-- count this
    }
}
```', '{"A":"6","B":"12","C":"36","D":"64"}', 'C', NULL, 'Outer 6 × inner 6 = `36` executions (quadratic — n²). No Big-O needed, just the count.', NULL, NULL, NULL),
  ('csa-ac-q38', 'ap_csa', '2.12', '2', 'P4', 'mcq', 'For input size `n`, how many times does `step()` run?
```java
for (int i = 0; i < n; i++) {
    step();           // loop A
}
for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
        step();       // loop B
    }
}
```', '{"A":"`n + n` = `2n`","B":"n + n²","C":"n²","D":"2n²"}', 'B', NULL, 'Loop A runs `step()` `n` times (linear); loop B runs it `n × n = n²` times (quadratic). Sequential blocks add: `n + n²`.', NULL, NULL, NULL),
