public class Locker {
    private int id;
    private String combination;
    private boolean occupied;

    public Locker(int idNumber, String combo) {
        id = idNumber;
        combination = combo;
        occupied = false;
    }

    public int getId() {
        return id;
    }

    public boolean unlock(String attempt) {
        return attempt.equals(combination);
