public class Player {
    private String name;
    private int score;
    private int lives;

    public Player(String playerName, int startLives) {
        name = playerName;
        lives = startLives;
        score = 0;
    }

    public int getScore() {
        return score;
    }

    public void addPoints(int p) {
        score += p;
    }

